"""Write docs/COMPONENTS.md from echos/components.py (the single registry the API and the UI also read). Do not edit the .md by hand.
Usage: PYTHONPATH=. python scripts/docgen/make_components_doc.py   (tests/test_team_v2.py fails if the file is out of date)"""
from __future__ import annotations

from pathlib import Path

from echos.components import COMPONENTS

ROOT = Path(__file__).resolve().parents[2]
KIND = {"agent": "Agent: its own process with a goal, a persistent belief (memory), its own decisions, and messages to the other agents. It learns from feedback.",
        "tool": "Tool: a method an agent calls. It computes; it never decides, sends or remembers anything on its own.",
        "infra": "Infrastructure: keeps the agents running and connected."}


def render() -> str:
    out = ["# Components: agents, tools and infrastructure", "",
           "Generated by `scripts/docgen/make_components_doc.py` from `echos/components.py`; the API (`GET /api/components`) and the web app (How it works) read the same registry.", "",
           "ECHOS watches the vital signs and home activity sensors of people living with dementia. It alerts the caregiver and clinician at once on a red-flag reading, "
           "and every day tells a small clinical team who to review and why, in plain words. Decision support, not a diagnosis; no model decides an emergency.", ""]
    for kind in ("agent", "tool", "infra"):
        out += [f"## {kind.capitalize()}s" if kind != "infra" else "## Infrastructure", "", KIND[kind], ""]
        for c in (x for x in COMPONENTS if x["kind"] == kind):
            out += [f"### {c['name']} (`{c['id']}`)", "", c["role"], "",
                    f"- **Takes in:** {c['inputs']}", f"- **Produces:** {c['outputs']}", f"- **If it fails:** {c['on_failure']}", f"- **Never:** {c['never']}", ""]
    out += ["## How they talk", "",
            "Only through the SQLite message bus (`agent_message`, `echos/team/bus.py`):", "",
            "- Patient Monitor -> Care agent: `urgent` (a red-flag reading)",
            "- Care agent -> Patient Monitor: `feedback` (the day's confirmed outcome: the learning signal)",
            "- Patient Monitor -> Review Coordinator: `review_request` (risks + plain-words reasons)",
            "- Review Coordinator -> Care agent: `assign` (one per selected person); -> Patient Monitors: `review_decision`",
            "- Clinician (API) -> Care agent: `clinician_outcome`", "",
            "The web app shows the live trace on the *Agents* page and each person's messages on their page.", ""]
    return "\n".join(out)


if __name__ == "__main__":
    (ROOT / "docs" / "COMPONENTS.md").write_text(render())
    print("wrote docs/COMPONENTS.md")
